import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const defaultRoot = fileURLToPath(new URL("../", import.meta.url));
const registryFile = "tooling/shared-helpers.registry.json";
// Handwritten Lua only. lua/endpoints is generated by build-lua.js from these directories.
const scannedDirectories = ["lua/shared", "lua/src"];

// Matches `function name(`, `function M.name(`, `function M:name(` and `M.name = function(`.
// Only the last segment is the helper's name, so a module-table copy is still a copy.
const DEFINITION_PATTERNS = [
  /^\s*(?:local\s+)?function\s+([A-Za-z_][\w.:]*)\s*\(/,
  /^\s*(?:local\s+)?([A-Za-z_][\w.]*)\s*=\s*function\s*\(/,
];

// The same shapes anchored at column 0: only these count as a shared helper's definition.
const TOP_LEVEL_PATTERNS = DEFINITION_PATTERNS.map(
  (pattern) => new RegExp(pattern.source.replace("^\\s*", "^")),
);

// Every top-level function in lua/shared is protected. It is not a registry family, so it has no patterns.
const SHARED_FAMILY = {
  id: "shared-helper",
  description: "a function already defined in lua/shared",
  homes: [],
};

async function luaFiles(root, directory) {
  const entries = await readdir(path.join(root, directory), { withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile() && entry.name.endsWith(".lua"))
    .map((entry) => `${directory}/${entry.name}`)
    .sort();
}

function definitionName(line, patterns = DEFINITION_PATTERNS) {
  for (const pattern of patterns) {
    const match = pattern.exec(line);
    if (match) return match[1].split(/[.:]/).pop();
  }
  return null;
}

function stripComment(line) {
  const index = line.indexOf("--");
  return index === -1 ? line : line.slice(0, index);
}

function familyProblems(family, seen) {
  const problems = [];
  if (!family.id || seen.has(family.id))
    problems.push(`family id missing or duplicated: ${family.id}`);
  seen.add(family.id);
  if (!family.description) problems.push(`family ${family.id} needs a description`);
  if (!Array.isArray(family.homes)) problems.push(`family ${family.id} needs a homes array`);
  if (family.homes?.length === 0 && !family.unowned) {
    problems.push(
      `family ${family.id} has no homes; set "unowned": "<what to do first>" or name the shared file where its patterns belong`,
    );
  }
  if (!family.lookalikes?.length && !family.inline?.length) {
    problems.push(`family ${family.id} needs "lookalikes" or "inline" patterns`);
  }
  return problems;
}

function allowlistEntryProblems(entry) {
  const problems = [];
  if (entry.count !== undefined && !(Number.isInteger(entry.count) && entry.count >= 1)) {
    problems.push(
      `allowlist entry ${JSON.stringify(entry)} has an invalid "count"; use a positive integer`,
    );
  }
  for (const key of ["file", "family", "symbol", "reason"]) {
    if (typeof entry[key] !== "string" || !entry[key].trim()) {
      problems.push(
        `allowlist entry ${JSON.stringify(entry)} needs a nonempty "${key}" (reason says why the copy must stay)`,
      );
    }
  }
  return problems;
}

/** Throws one error listing every problem in the registry itself, so a bad edit fails loudly. */
function validateRegistry(registry) {
  const seen = new Set();
  const problems = [
    ...(registry.families ?? []).flatMap((family) => familyProblems(family, seen)),
    ...(registry.allowlist ?? []).flatMap(allowlistEntryProblems),
  ];
  if (problems.length > 0) {
    throw new Error(`Invalid ${registryFile}:\n- ${problems.join("\n- ")}`);
  }
}

function registryFindings(registry, sources) {
  return registry.families.flatMap((family) =>
    family.homes
      .filter((home) => !sources.has(home))
      .map((home) => ({
        message: `${registryFile}: family "${family.id}" home ${home} does not exist. Update the path or remove it.`,
      })),
  );
}

function homeHint(family) {
  if (family.homes.length === 0) {
    return `No shared helper exists yet (${family.unowned}).`;
  }
  return `Use the shared helper from ${family.homes.join(" or ")} (declare it in the module's sharedSourcePaths).`;
}

/** Maps each top-level function name in lua/shared to the first file that defines it. */
function sharedHelperOwners(sources) {
  const owners = new Map();
  for (const [file, source] of sources) {
    if (!file.startsWith("lua/shared/")) continue;
    for (const line of source.split("\n")) {
      const name = definitionName(stripComment(line), TOP_LEVEL_PATTERNS);
      if (name && !owners.has(name)) owners.set(name, file);
    }
  }
  return owners;
}

function patternFindings(family, file, lines, shared) {
  const findings = [];
  const lookalikes = (family.lookalikes ?? []).map((pattern) => new RegExp(pattern));
  const inline = (family.inline ?? []).map((rule) => ({
    ...rule,
    regex: new RegExp(rule.pattern),
  }));
  lines.forEach((rawLine, index) => {
    const line = stripComment(rawLine);
    const name = definitionName(line);
    // A copy of a name another shared file defines is reported once, as a shared-helper copy.
    const owner = name && shared.get(name);
    if (name && (!owner || owner === file) && lookalikes.some((regex) => regex.test(name))) {
      findings.push({ kind: "lookalike", file, line: index + 1, family, symbol: name });
    }
    for (const rule of inline) {
      if (rule.regex.test(line)) {
        findings.push({ kind: "inline", file, line: index + 1, family, symbol: rule.id, rule });
      }
    }
  });
  return findings;
}

function sourceFindings(registry, sources) {
  const shared = sharedHelperOwners(sources);
  const findings = [];
  for (const [file, source] of sources) {
    const lines = source.split("\n");
    lines.forEach((rawLine, index) => {
      const line = stripComment(rawLine);
      const name = definitionName(line);
      const owner = name && shared.get(name);
      // Inside lua/shared only a top-level definition can be a second copy; nested locals are private.
      const counts = file.startsWith("lua/shared/")
        ? definitionName(line, TOP_LEVEL_PATTERNS) === name
        : true;
      if (owner && owner !== file && counts) {
        findings.push({
          kind: "redefinition",
          file,
          line: index + 1,
          family: SHARED_FAMILY,
          symbol: name,
          owner,
        });
      }
    });
    for (const family of registry.families) {
      if (family.homes.includes(file)) continue;
      findings.push(...patternFindings(family, file, lines, shared));
    }
  }
  return findings;
}

function findingMessage(finding, allowedCount) {
  const { kind, file, line, family, symbol, rule, count } = finding;
  const hint =
    kind === "redefinition"
      ? `Use ${symbol} from ${finding.owner} (declare it in the module's sharedSourcePaths), or rename this one.`
      : homeHint(family);
  const where = `${file}:${line}`;
  const what = {
    redefinition: () =>
      `defines "${symbol}", which lua/shared already defines in ${finding.owner}.`,
    lookalike: () =>
      `defines "${symbol}", which looks like a new copy of the ${family.id} helpers (${family.description}).`,
    inline: () => `re-implements ${rule.description} inline (${family.description}).`,
  }[kind]();
  const entry = JSON.stringify({
    file,
    family: family.id,
    symbol,
    ...(count > 1 ? { count } : {}),
    reason: "<why this copy must stay>",
  });
  const advice =
    allowedCount === undefined
      ? `If the copy must stay, add to "allowlist" in ${registryFile}:`
      : `The allowlist covers ${allowedCount} occurrence(s) but ${count} exist now. Remove the new copy, or raise "count" with a reason:`;
  return [`${where}: ${what}`, `  ${hint} ${advice}`, `  ${entry}`].join("\n");
}

function allowlistKey(file, family, symbol) {
  return `${file}\u0000${family}\u0000${symbol}`;
}

/**
 * Checks handwritten Lua against the shared-helper registry.
 * Returns { errors: string[] }; an empty list means the check passed.
 */
async function checkSharedHelpers() {
  const root = defaultRoot;
  const loaded = JSON.parse(await readFile(path.join(root, registryFile), "utf8"));
  validateRegistry(loaded);

  const files = (await Promise.all(scannedDirectories.map((dir) => luaFiles(root, dir)))).flat();
  const sources = new Map(
    await Promise.all(
      files.map(async (file) => [file, await readFile(path.join(root, file), "utf8")]),
    ),
  );

  const errors = registryFindings(loaded, sources).map((finding) => finding.message);
  const allowed = new Map(
    (loaded.allowlist ?? []).map((entry) => [
      allowlistKey(entry.file, entry.family, entry.symbol),
      entry,
    ]),
  );
  const used = new Set();
  // One report per file, family and symbol: the unit an allowlist entry covers.
  const grouped = new Map();
  for (const finding of sourceFindings(loaded, sources)) {
    const key = allowlistKey(finding.file, finding.family.id, finding.symbol);
    const existing = grouped.get(key);
    if (existing) existing.count += 1;
    else grouped.set(key, { ...finding, count: 1 });
  }
  for (const [key, finding] of grouped) {
    const entry = allowed.get(key);
    if (!entry) {
      errors.push(findingMessage(finding));
      continue;
    }
    used.add(key);
    const allowedCount = entry.count ?? 1;
    if (finding.count > allowedCount) errors.push(findingMessage(finding, allowedCount));
    else if (finding.count < allowedCount) {
      errors.push(
        `${registryFile}: allowlist entry for ${entry.file} / ${entry.family} / ${entry.symbol} allows ${allowedCount} but only ${finding.count} remain. Lower or remove "count".`,
      );
    }
  }
  for (const [key, entry] of allowed) {
    if (!used.has(key)) {
      errors.push(
        `${registryFile}: allowlist entry for ${entry.file} / ${entry.family} / ${entry.symbol} matches nothing. The copy was removed or renamed; delete the entry.`,
      );
    }
  }
  return { errors };
}

async function main() {
  const { errors } = await checkSharedHelpers();
  if (errors.length > 0) {
    process.stderr.write(
      `Shared helper check failed (${errors.length}):\n\n${errors.join("\n\n")}\n`,
    );
    process.exitCode = 1;
    return;
  }
  process.stdout.write("Shared helper check passed.\n");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    await main();
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 1;
  }
}
